local additions={[47]={["opening"]="Kobolds around Elwynn carried gold dust that Remy \"Two Times\" wanted to buy. His leads pointed to Fargodeep and Jasperlode.",["atomIDs"]={"47:description:1-61","47:description:64-178","47:description:183-287"},["sourceHash"]="21dd8e6616fbed8e6132edc094471cea3ffec2ebafed2f3af7b7cb89c02f345b",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[54]={["opening"]="The charge of protecting Northshire was widening to the surrounding forest. Marshal McBride had prepared papers for Marshal Dughan in Goldshire.",["atomIDs"]={"54:description:71-142","54:description:147-253"},["sourceHash"]="f9001c62c3fc8b71ad2afff83f53059b3ca98643524eff865a1b10e6ab2a9d41",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[60]={["opening"]="William Pestle needed candle wax for the apothecary he ran with his brother in Stormwind. Rumors of kobolds in Elwynn’s mines offered a place to look.",["atomIDs"]={"60:description:55-154","60:description:177-281","60:description:283-346"},["sourceHash"]="f263351cae6036d2acd50e0d1c530157468e538446f33535e77a9d2ed105ac13",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[61]={["opening"]="Morgan Pestle was waiting in Stormwind for his brother’s shipment of candles. William had packed the cargo for their shop in the Trade District.",["atomIDs"]={"61:description:1-69","61:description:189-306"},["sourceHash"]="d7584c6b4d56e0de4a46694c2caa479c9f9130466bd800ef850dc49cbbf052f8",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[64]={["opening"]="Farmer Furlbrow had fled his farm in haste, leaving behind the pocket watch given to him on his wedding day. He believed the thieves still had it.",["atomIDs"]={"64:description:73-106","64:description:109-163","64:description:166-265","64:description:268-324"},["sourceHash"]="443a3f052e05e1250f33543606479146a228dde4b7323beeee962c7baac0c8c1",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[83]={["opening"]="Sara Timberlain could turn the red linen worn by Elwynn’s Defias into useful goods. She wanted their bandanas for the cloth.",["atomIDs"]={"83:description:1-127","83:description:132-206"},["sourceHash"]="325119ae782909cdf25c27dd05b5ab695c12d5c8347e0e62d95a67a95679529b",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[85]={["opening"]="A missing necklace had set a widow against Billy Maclure. She suspected the boy of taking it; the accusation still needed an answer.",["atomIDs"]={"85:description:1-69","85:description:72-147","85:description:153-218"},["sourceHash"]="069252413ee8eaa0d4766d1558ddcaaf4e7e38854f6f41748ce8c0e84a7fd31e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[86]={["opening"]="Billy offered a lead on the necklace in exchange for a pie. He suggested bringing boar meat to Bernice at the neighboring farm.",["atomIDs"]={"86:description:1-61","86:description:64-156","86:description:162-309"},["sourceHash"]="983d939713bd87453c856439f788ec6681577e59eeba21f3bc4601c9b4f6109a",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[88]={["opening"]="The Brackwells’ enormous pig, Princess, had been eating Ma Stonefield’s vegetables. Ma wanted the sow stopped before another visit to her fields.",["atomIDs"]={"88:description:1-50","88:description:53-136","88:description:141-194","88:description:383-433"},["sourceHash"]="7e097c57e80ac4fafa3eea4e51cfc0effddf6d7d4118ca8a3afcb9c8fd942467",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[106]={["opening"]="Maybell Maclure loved Tommy Joe Stonefield, but the two families were bitter enemies. A letter offered a way to reach him despite their separation.",["atomIDs"]={"106:description:18-95","106:description:98-174","106:description:179-228"},["sourceHash"]="fb57860687693d6223cc69493caa74ad26abc32036c2d2cf15eed5b771f2f6f3",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[109]={["opening"]="Gryan Stoutmantle led the People’s Militia in defense of Westfall’s farms. A report to him at Sentinel Hill could lead to work in that troubled country.",["atomIDs"]={"109:description:66-128","109:description:131-210","109:description:213-241","109:description:244-349"},["sourceHash"]="109ca833fa78af18f47ce78c72e6781d5b8d0b1a5d48aed9bc786f29910bcad6",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[112]={["opening"]="William Pestle proposed an invisibility liquor to help Maybell reach Tommy Joe. For the mixture he needed crystal kelp, which murlocs sometimes gathered.",["atomIDs"]={"112:description:1-115","112:description:118-166","112:description:171-217","112:description:219-247","112:description:250-295"},["sourceHash"]="35ae5a7096f2b635adaaf82905a874605c0095890479d17db1a0857c643aff26",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[114]={["opening"]="The liquor was ready for Maybell. William expected its concealment to last long enough for her to visit Tommy Joe.",["atomIDs"]={"114:description:1-47","114:description:50-103"},["sourceHash"]="bffeb5787f11f8c3230b575e49ec4932628d3a5affbcf489c7121c9514701739",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[176]={["opening"]="Hogger had overpowered attempts to capture him in southwestern Elwynn. The Stormwind Army offered a bounty, with proof to be brought to Marshal Dughan.",["atomIDs"]={"176:description:19-85","176:description:88-134","176:description:139-199","176:description:202-305"},["sourceHash"]="e3ed6754a117194bb78692507a4f61b5673fecc960b46031e81208eb4e3e14b8",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},[239]={["opening"]="Gnolls and thieves were becoming more active along Elwynn’s western border. Westbrook Garrison had asked for soldiers, but none could be spared.",["atomIDs"]={"239:description:1-85","239:description:88-140","239:description:142-177","239:description:217-301"},["sourceHash"]="f01fdb92c3f282f9c0159f0c8bddb96a717c224758439eefd543921071a66592",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}}
for id,row in pairs(additions) do assert(not ns.AthenaQuestContextData[id],"Duplicate editorial override");ns.AthenaQuestContextData[id]=row end

-- Additional reviewed regional/class scenes; no completion or graph inference.
do
local additions={[26]={["opening"]="The creatures of the water were the next subject of druid training. Mathrengyl Bearwalker directed the student to Dendrite Starblaze in Nighthaven, where the Cenarion Circle kept its sanctuary.",["atomIDs"]={"26:description:1-58","26:description:61-137","26:description:142-338","26:description:341-471","26:description:474-499","26:objective:1-70"},["sourceHash"]="2fc9cc916493b77c543b94d0ef2f7a0deb1d86840954daa49f3e1ff186144d70",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} spoke with Dendrite Starblaze in Nighthaven.",["baseOverrideRevision"]=1,["baseOverrideSetup"]="Druid training turned toward the creatures of the water. The next lesson lay with Dendrite Starblaze in Nighthaven."},[27]={["opening"]="Turak Runetotem sent the student to Nighthaven in Moonglade. There, Dendrite Starblaze would introduce the aquatic aspect of druid training.",["atomIDs"]={"27:description:1-58","27:description:61-137","27:description:142-338","27:description:341-471","27:description:474-499","27:objective:1-70"},["sourceHash"]="564248f30f2f8643885b62d8c5a200955aba7b2a95ec4463a04afc58a1ac6bee",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} spoke with Dendrite Starblaze in Nighthaven.",["baseOverrideRevision"]=1,["baseOverrideSetup"]="Druid training turned toward the creatures of the water. The next lesson lay with Dendrite Starblaze in Nighthaven."},[28]={["opening"]="The first trial demanded speed as well as a steady hand. A shrine bauble hidden in Lake Elune’ara had to reach the Shrine of Remulos before its magic faded; Tajarri waited there to judge the work.",["atomIDs"]={"28:description:1-84","28:description:87-160","28:description:163-274","28:description:279-414","28:description:417-479","28:description:484-497","28:objective:1-103","28:objective:106-139","28:objective:144-227"},["sourceHash"]="b8e721782ff375985b001d8480610991e9434119f86e3888a9df62b87a48b8bb",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} completed the trial of the bauble and reported to Tajarri.",["baseOverrideRevision"]=1,["baseOverrideSetup"]="A bauble hidden in Lake Elune’ara formed the heart of a trial: carry its fading magic to the Shrine of Remulos."},[29]={["opening"]="Dendrite’s trial began beneath Lake Elune’ara. The shrine bauble’s magic would not last: it had to be carried to the Shrine of Remulos, where Tajarri awaited the student.",["atomIDs"]={"29:description:1-84","29:description:87-160","29:description:163-274","29:description:279-414","29:description:417-479","29:description:484-497","29:objective:1-103","29:objective:106-139","29:objective:144-227"},["sourceHash"]="4045629255f288d76a55f85dc285df81b1135e18c82019c9c7d9e7028f760d1c",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} completed the trial of the bauble and reported to Tajarri.",["baseOverrideRevision"]=1,["baseOverrideSetup"]="A bauble hidden in Lake Elune’ara formed the heart of a trial: carry its fading magic to the Shrine of Remulos."},[30]={["opening"]="Tajarri’s next lesson joined agility with endurance, the sea lion’s two strengths. Each was represented by half a pendant; the pieces had to be found and joined before returning to Dendrite.",["atomIDs"]={"30:description:1-87","30:description:90-249","30:description:252-335","30:description:340-450","30:description:453-504","30:objective:1-83","30:objective:86-177","30:objective:182-242","30:objective:245-308","30:objective:313-399"},["sourceHash"]="5d4aad6a491b54fc4456741a9ea27458aef8b7162046efe794a6044592ec567e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} brought the joined pendant to Dendrite Starblaze.",["baseOverrideRevision"]=1,["baseOverrideSetup"]="The sea lion’s agility and endurance were embodied in two halves of a pendant. Joining them would express both aspects together."},[272]={["opening"]="The sea lion’s agility and endurance were embodied in two halves of a pendant. Tajarri required both: the student would have to seek them out, join them, and bring the pendant to Dendrite.",["atomIDs"]={"272:description:1-87","272:description:90-249","272:description:252-335","272:description:340-450","272:description:453-504","272:objective:1-83","272:objective:86-177","272:objective:182-242","272:objective:245-308","272:objective:313-399"},["sourceHash"]="b55d693beb938612d0ec18aa59825288c32ef9e85c67df4dc035ab9dd2c9155d",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} brought the joined pendant to Dendrite Starblaze.",["baseOverrideRevision"]=1,["baseOverrideSetup"]="The sea lion’s agility and endurance were embodied in two halves of a pendant. Joining them would express both aspects together."},[31]={["opening"]="The pendant was proof of the lessons Dendrite had set. He now directed the student back to Turak Runetotem in Thunder Bluff for the final part of the aquatic training.",["atomIDs"]={"31:description:1-109","31:description:112-174","31:description:177-263","31:description:266-339","31:description:344-364","31:description:367-387","31:objective:1-77"},["sourceHash"]="66488cfae7d30d9839803e54a025c72f05dbc783bc97e80e40cd52c6f7391c68",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} showed the pendant to Turak Runetotem.",["baseOverrideRevision"]=2,["baseOverrideSetup"]="The pendant was to be brought to Turak Runetotem in Thunder Bluff as proof of the druid’s lessons."},[5061]={["opening"]="Dendrite’s lessons led back to Mathrengyl Bearwalker in Darnassus. The pendant was to serve as proof that the student was ready for the final aquatic training.",["atomIDs"]={"5061:description:1-109","5061:description:112-176","5061:description:179-265","5061:description:268-341","5061:description:346-366","5061:description:369-389","5061:objective:1-79"},["sourceHash"]="c076b97893fb1fccf9e2fd241eb0e8fcdda9959a216917417cd5003a57ed2b10",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} showed the pendant to Mathrengyl Bearwalker.",["baseOverrideRevision"]=2,["baseOverrideSetup"]="The pendant was to be brought to Mathrengyl Bearwalker in Darnassus as proof of the druid’s lessons."},[363]={["opening"]="Deathknell’s crypt had a caretaker: Undertaker Mordo. For one newly freed from the Lich King, he could offer only a beginning; Shadow Priest Sarvis, in the chapel below the hill, could explain more.",["atomIDs"]={"363:description:1-23","363:description:25-111","363:description:116-168","363:description:170-211","363:description:216-330"},["sourceHash"]="61a13f0010c399131204716385c754bc6421e06020ace516ca23c3d3e6ea651f",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[364]={["opening"]="The Forsaken were at war with the Scourge. North of Deathknell, former kin still wandered as mindless servants of the Lich King; Sarvis’s charge was to put those lost souls to rest.",["atomIDs"]={"364:description:1-159","364:description:164-266","364:description:268-350","364:description:352-401","364:objective:1-81"},["sourceHash"]="d25c95638fc8ade4dea16403031e6e1f3c9798db81694bd728f56ed596d6578e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="Sarvis’s charge against the mindless undead was fulfilled."},[365]={["opening"]="The farm west of Brill remained in human hands, with a Scarlet tower nearby. Deathguard Simmer wanted its pumpkins stolen and taken to Apothecary Johaan.",["atomIDs"]={"365:description:1-18","365:description:21-49","365:description:52-142","365:description:147-177","365:description:180-232","365:description:235-301","365:description:304-369","365:description:374-431"},["sourceHash"]="f015eff1d9ab933afd2b0fa31eb654dd231d1d8c38d05edbdabe9a8d01c3a019",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[367]={["opening"]="Sylvanas had called on the Royal Apothecary Society to find a weapon against Arthas. Johaan’s answer was a deadlier plague, beginning with an experiment using the blood of darkhounds.",["atomIDs"]={"367:description:1-59","367:description:61-169","367:description:172-264","367:description:266-323","367:description:328-394","367:description:396-458"},["sourceHash"]="0f5b9777793f36d6e8963dfa322b12b9fb292703ff39d0b901519250d0b7fde3",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[368]={["opening"]="Johaan wanted more than a poison that killed its first victim. For a plague capable of spreading, he needed another reagent: scales from the Vile Fin murlocs along the coast north and west of Brill.",["atomIDs"]={"368:description:1-151","368:description:153-198","368:description:200-260","368:description:265-323","368:description:326-397"},["sourceHash"]="6a426a36c8bb4d28e1ffb8746262f7c1ae15e73864e445a53fbc07d8288639dd",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[369]={["opening"]="An old account of a contagious plague gave Johaan another lead. He believed venom from a Vicious Night Web Spider could preserve the spreading agent his experiment still lacked.",["atomIDs"]={"369:description:1-153","369:description:156-268","369:description:273-352","369:description:355-442","369:description:445-509"},["sourceHash"]="1afb471e5cba60be8cb9d011af0a99fe663993e303ec054c420e9d64993e1c50",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[370]={["opening"]="The Scarlet Crusade’s plans had reached Executor Zygand. His next target was Captain Perrine’s brigade, stationed at a ruined tower southwest of Brill.",["atomIDs"]={"370:description:1-121","370:description:124-255","370:description:260-334","370:objective:1-105"},["sourceHash"]="81bf4e2b810d47f749e57f27a00de3ba7f748c45d4810c1bf4eb0c7368fee04e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="Zygand’s charge against Perrine and his brigade was fulfilled."},[371]={["opening"]="Scarlet raiders still threatened the countryside. Zygand traced their attacks to Captain Vachon at a ruined tower southeast of Brill, near the Balnir Farmstead.",["atomIDs"]={"371:description:1-62","371:description:65-253","371:description:258-297","371:description:299-354","371:objective:1-90"},["sourceHash"]="52db2e170f5c95ef5884bef10f4df1f917576353dbd5e4f7db1a7b3fee4738ff",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} fulfilled Zygand’s charge against Vachon and the Scarlet Friars."},[372]={["opening"]="Zygand’s campaign against the Scarlet Crusade turned north, beyond Faol’s Rest. Captain Melrache and his bodyguards were the next targets of the raids against the Scarlet towers.",["atomIDs"]={"372:description:1-97","372:description:100-212","372:description:217-277","372:description:280-346"},["sourceHash"]="bb18eecfadd4df05cd262dcba4dcabc87129f287613a68e687ca99949ac1fdf7",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[376]={["opening"]="Novice Elreth helped Sarvis tend Deathknell’s wounded. In exchange for wolf paws and bat wings from the lands to the south, she could find armor for someone willing to help.",["atomIDs"]={"376:description:1-148","376:description:153-214","376:description:216-261","376:description:263-349","376:description:351-440","376:description:442-499","376:objective:1-60"},["sourceHash"]="f4e564550551300a618d1bdcc8ba56aa45b95d411564fb73d3ca4c9bbee89ea3",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} brought Elreth the paws and wings she required."},[380]={["opening"]="Deathknell needed resources to survive, but spiders had overrun its gold mine to the northwest. With too few hands to clear the place at once, Executor Arren called for a gradual attack on the infestation.",["atomIDs"]={"380:description:1-84","380:description:86-144","380:description:149-221","380:description:223-327","380:description:329-419","380:description:424-471","380:objective:1-84"},["sourceHash"]="6e35feae51f98dee0fc0dc128253f41191164d3583f40c21baf2f1e7a562bd7e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="Arren’s charge against the mine’s spiders was fulfilled."},[381]={["opening"]="Scarlet scouts had made camp southeast of Deathknell. They hunted undead without distinguishing the Forsaken from the Scourge, and Arren feared what their zeal would bring to the village.",["atomIDs"]={"381:description:1-109","381:description:112-154","381:description:159-262","381:description:264-410","381:description:412-432","381:description:437-499","381:objective:1-85"},["sourceHash"]="b6378b2a389bf1a2678c46f0aebaf3dd2f8ae6452d4abd6a86009086bc32f2f4",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} brought Arren the Scarlet armbands."},[382]={["opening"]="A messenger from the Scarlet Monastery was expected near Deathknell. Arren did not know what information the courier carried, but believed it important enough to recover.",["atomIDs"]={"382:description:1-151","382:description:153-238","382:description:240-306","382:description:311-362","382:description:364-430"},["sourceHash"]="ad774deacfcd9f660bffe652c669491590f546d8262719991decf2eab8dc475a",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[383]={["opening"]="The recovered intelligence belonged in Brill. Arren wanted Executor Zygand to have it so that the Forsaken could plan their next move against the Scarlet Crusade.",["atomIDs"]={"383:description:1-70","383:description:72-155","383:description:157-315","383:description:320-357","383:description:359-419","383:description:421-463","383:description:465-508"},["sourceHash"]="e22955a51cd4281cfad785606a12bcce68a29494f75e0d4a3440fc23409445ce",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[398]={["opening"]="Maggot Eye was accused of stealing corpses for the Scourge. The wanted notice placed him at Garren’s Haunt, north of Brill, and called for his paw as proof to Executor Zygand.",["atomIDs"]={"398:description:1-19","398:description:24-137","398:description:140-221","398:description:224-310","398:description:315-407","398:description:410-470","398:description:475-496"},["sourceHash"]="9e398b2840862bf0f2aac63e44bc2a8a0ceeb17b32c71a2a9a5f12596327600b",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[404]={["opening"]="The Scourge were gathering west of Brill near the old bridge. Deathguard Dillinger wanted the rotting dead and ravaged corpses confronted, with their claws brought back as proof.",["atomIDs"]={"404:description:1-105","404:description:110-178","404:description:181-271"},["sourceHash"]="1c4a4d6eff54cce92596f23a4319d6d4d2f41b0b38ca51f3748aad88f9543a6a",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[9]={["opening"]="Thieves had driven Westfall’s farmers from their land, but Farmer Saldean refused to leave. Harvest Watchers had taken over his fields, and he needed them cleared before the land could be worked.",["atomIDs"]={"9:description:1-40","9:description:43-91","9:description:94-141","9:description:144-158","9:description:161-222","9:description:227-300","9:description:303-342","9:description:345-435","9:objective:1-53"},["sourceHash"]="c81552d17de719e6e330882a5d97ad8ed44495b5aae5630ce4656c15d416a151",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="Saldean’s charge against the Harvest Watchers was fulfilled."},[12]={["opening"]="The People’s Militia existed to defend Westfall and restore its peace. Stoutmantle’s scouts now reported Defias Trappers near the Jangolode Mine and the northern farms.",["atomIDs"]={"12:description:1-109","12:description:112-160","12:description:166-250","12:description:253-394","12:description:396-492","12:objective:1-115"},["sourceHash"]="ca931237fbf24d9fb1703086d37ba10225b4b81652c6587e2a0b33480b1a8ead",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} fulfilled Stoutmantle’s charge against the Defias Trappers and Smugglers."},[13]={["opening"]="The fighting spread to the Gold Coast Quarry, Moonbrook and the Alexston Farmstead. Defias Pillagers were plundering those places, and Stoutmantle meant the militia to stop them.",["atomIDs"]={"13:description:1-120","13:description:123-176","13:description:179-252","13:description:257-322","13:description:325-434","13:objective:1-113"},["sourceHash"]="1fef918ba4b0dad5a4de6c2995e82cb31bf8ba8619304923676793fa9bd43794",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="Stoutmantle’s charge against the Defias Pillagers and Looters was fulfilled."},[14]={["opening"]="Some of the Defias had escaped the militia’s reach. Reports of looting in southern Westfall led Stoutmantle to suspect a hiding place in the Dagger Hills.",["atomIDs"]={"14:description:1-27","14:description:30-161","14:description:164-240","14:description:244-297","14:objective:1-144"},["sourceHash"]="5c5fc160b5383908e2751ba58769806ce196a8506de7746c0b7e8518c2024d40",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} fulfilled the militia’s charge against the Highwaymen, Pathstalkers and Knuckledusters."},[22]={["opening"]="Salma Saldean had prepared the crust, herbs and gravy for her meat pie. Only the goretusk livers were missing.",["atomIDs"]={"22:description:1-22","22:description:25-45","22:description:48-71","22:description:74-98","22:description:101-125","22:description:128-150","22:description:153-212","22:objective:1-67"},["sourceHash"]="2df58ccc6dbcf5b0a6e92b0144b53e7c462964d90552120cf4c66a172a590c1b",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} supplied the livers for Salma’s pie."},[33]={["opening"]="Eagan Peltskinner had little affection for Northshire’s timber wolves, though he enjoyed their meat. He offered useful goods in exchange for meat from the wolves roaming the countryside.",["atomIDs"]={"33:description:1-33","33:description:36-72","33:description:75-155","33:description:160-272"},["sourceHash"]="004b915525b8f48a114b0eec43344ea955c5fc00a39fc96a842b6b73abe446ca",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[36]={["opening"]="Thieves had made the Furlbrows’ farm too dangerous to keep. While her husband repaired their wagon, Verna entrusted her stew recipe to a traveler bound for Salma Saldean’s farm.",["atomIDs"]={"36:description:1-59","36:description:62-144","36:description:147-215","36:description:223-252","36:description:255-303","36:description:306-361","36:description:364-418"},["sourceHash"]="f9abda536f0e38d90ff11e0ebb4a6b2b571df305cbdf9a4f754d0e5b43752d70",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[38]={["opening"]="Salma Saldean’s stew drew on what Westfall could provide: vulture meat, goretusk snouts, murloc eyes and okra. Those were the ingredients she still needed.",["atomIDs"]={"38:description:1-32","38:description:35-76","38:description:82-105","38:description:108-126","38:description:129-143","38:description:146-152","38:objective:1-85"},["sourceHash"]="6baed7bc732b626afc42f78fac19a62169ce5c8dca3a99d56ea5efa0cff03511",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} supplied the ingredients for Salma’s stew."},[46]={["opening"]="The Stormwind Army had placed a bounty on Elwynn’s murlocs. Guard Thomas pointed to their villages at Stone Cairn Lake and the fork of the stream; torn fins would serve as proof.",["atomIDs"]={"46:description:1-80","46:description:83-178","46:description:183-298"},["sourceHash"]="c7e98c786fd491656d3701b0d692eebb0e2c54dedede695e29bd991c227c51ab",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[52]={["opening"]="Beyond Goldshire, the forest’s animals were growing more aggressive. Wolves and bears attacked the Eastvale Logging Camp so often that Guard Thomas needed help defending it.",["atomIDs"]={"52:description:1-9","52:description:12-180","52:description:185-216"},["sourceHash"]="d484633ff9f33e95cc5b17b90073e6a0ed0e480bbc889e0ffdc281b6f0f44a18",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[117]={["opening"]="Grimbooze Thunderbrew’s lager still needed hops. Without them, his verse warned, the brew tasted rather more like stew than beer.",["atomIDs"]={"117:description:1-34","117:description:37-73","117:description:76-110","117:description:113-145"},["sourceHash"]="65dd0b9211ea10c18ca4a0aa504a4eb03c4d31b09cd2d3d6f31d703645da9fd2",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[118]={["opening"]="Keeping the Stormwind Guards equipped had exhausted Verner Osgood’s iron. The stable’s horses still needed shoes, so he prepared a request for Blacksmith Argus in Goldshire.",["atomIDs"]={"118:description:1-130","118:description:135-182","118:description:185-252","118:objective:1-47"},["sourceHash"]="392dd314ca36b473b11b3e01f8e1399bf113c507ecd9decd624f52fd71bba7e1",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} brought Verner’s request to Smith Argus in Goldshire."},[119]={["opening"]="Argus had boxed up the fifty horseshoes Verner needed. The shipment was ready to return, with a note attached for the smith to read.",["atomIDs"]={"119:description:1-38","119:description:43-86","119:description:89-187","119:objective:1-36","119:objective:39-71"},["sourceHash"]="1599e58a77aa13b77f039ed4ce39e1f72617222abc17754facc729a236b6ce7e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} returned to Verner with the crate of horseshoes."},[120]={["opening"]="The township was under constant siege, and Magistrate Solomon feared defeat without reinforcements. His report had to reach General Marcus Jonathan in Stormwind, with any answer brought back quickly.",["atomIDs"]={"120:description:1-27","120:description:30-66","120:description:69-122","120:description:125-181","120:description:184-251","120:description:254-335","120:description:341-355","120:objective:1-106","120:objective:109-183"},["sourceHash"]="ae0fd9daac2bb3bbea0182ac688c1811938445515ab48818196850cc9eea5756",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} delivered Solomon’s report to Marcus Jonathan and returned to the magistrate."},[121]={["opening"]="Marcus Jonathan was still waiting for the King’s response. In the meantime, he had a letter for Magistrate Solomon.",["atomIDs"]={"121:description:1-96","121:description:102-115"},["sourceHash"]="a941f0f69a93a921392893cdd1b6b19d83cdc90687251af41d7bbc59cb718057",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]=""},[122]={["opening"]="Verner still had to pay Argus for the horseshoes. Scales from the black dragon whelps south of Lakeshire could settle that debt and leave something for the person who gathered them.",["atomIDs"]={"122:description:1-105","122:description:108-173","122:description:175-224","122:description:229-316","122:description:319-389","122:objective:1-103"},["sourceHash"]="edae885689ceccf27eb52f4a730fdda18ed23612ac19daea94f687d6f3f397c4",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["editorialVersion"]="journal-context-2.11.2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["pending"]="",["result"]="{actor} brought the whelp scales to Verner."}}
